// Core tests: the 13 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC's tests section. Every expected value below was computed by hand
// from the SPEC's rules (exact rational Widmark arithmetic: A = volume
// x ABV x 0.789, r male 0.68 / female 0.55, beta 0.15 g/L/h, breath
// = B / 2, band from the unrounded B, remaining minutes ceil(B x 400)).

import assert from "node:assert/strict";
import test from "node:test";
import { formatNumber, run } from "../public/js/core/bac-calculator.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

test("fixture count: 13 core and 3 controller cases are vendored", () => {
  assert.equal(coreCases.length, 13);
  assert.equal(fixtures.cases.filter((entry) => entry.kind === "controller").length, 3);
});

const base = {
  sex: "male",
  weightKg: "70",
  drinks: [{ volumeMl: "350", abvPercent: "5" }],
  elapsedMinutes: "0",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("the legal maximums stay exact: 500 kg, 5000 ml at 100%, 1440 min, 12 rows", () => {
  const drinks = Array.from({ length: 12 }, () => ({ volumeMl: "5000", abvPercent: "100" }));
  const outcome = run({ sex: "female", weightKg: "500", drinks, elapsedMinutes: "1440" });
  assert.equal(outcome.ok, true);
  // A = 12 x 5000 x 100% x 0.789 = 47340 g exactly; P = 47340 / (0.55 x 500)
  // = 172.145454...; B = P - 0.15 x 24 = 168.545454...; breath = B / 2.
  assert.deepEqual(outcome.result, {
    totalAlcoholGrams: 47340,
    peakBacGL: 172.145,
    bacGL: 168.545,
    bacPercent: 16.855,
    breathMgL: 84.273,
    band: "criminal",
    minutesToZero: 67419,
    minutesToBelowAdmin: 67299,
  });
});

test("the legal minimums: 20 kg, 1 ml at 0.1%, 0 min", () => {
  const outcome = run({
    sex: "male",
    weightKg: "20",
    drinks: [{ volumeMl: "1", abvPercent: "0.1" }],
    elapsedMinutes: "0",
  });
  assert.equal(outcome.ok, true);
  // A = 1 x 0.1% x 0.789 = 0.000789 g -> 0.0; P = 0.000789 / 13.6
  // = 0.0000580... -> 0.000; minutes ceil(0.0000580 x 400) = ceil(0.0232) = 1.
  assert.deepEqual(outcome.result, {
    totalAlcoholGrams: 0,
    peakBacGL: 0,
    bacGL: 0,
    bacPercent: 0,
    breathMgL: 0,
    band: "below-threshold",
    minutesToZero: 1,
    minutesToBelowAdmin: 0,
  });
});

test("weight 19.9 kg and 500.1 kg are RANGE; 20 and 500 pass", () => {
  assert.deepEqual(errorOf({ ...base, weightKg: "19.9" }), { code: "RANGE", field: "weightKg", row: null });
  assert.deepEqual(errorOf({ ...base, weightKg: "500.1" }), { code: "RANGE", field: "weightKg", row: null });
  assert.equal(run({ ...base, weightKg: "20" }).ok, true);
  assert.equal(run({ ...base, weightKg: "500" }).ok, true);
});

test("abv 0 and 0.0 are RANGE (must be > 0); 100 passes, 100.1 is RANGE", () => {
  assert.deepEqual(errorOf({ ...base, drinks: [{ volumeMl: "350", abvPercent: "0" }] }), {
    code: "RANGE",
    field: "abvPercent",
    row: 1,
  });
  assert.deepEqual(errorOf({ ...base, drinks: [{ volumeMl: "350", abvPercent: "0.0" }] }), {
    code: "RANGE",
    field: "abvPercent",
    row: 1,
  });
  assert.equal(run({ ...base, drinks: [{ volumeMl: "350", abvPercent: "100" }] }).ok, true);
  assert.deepEqual(errorOf({ ...base, drinks: [{ volumeMl: "350", abvPercent: "100.1" }] }), {
    code: "RANGE",
    field: "abvPercent",
    row: 1,
  });
});

test("volume 5001 is RANGE; 5000 passes; elapsed 1440 passes", () => {
  assert.deepEqual(errorOf({ ...base, drinks: [{ volumeMl: "5001", abvPercent: "5" }] }), {
    code: "RANGE",
    field: "volumeMl",
    row: 1,
  });
  assert.equal(run({ ...base, drinks: [{ volumeMl: "5000", abvPercent: "5" }] }).ok, true);
  assert.equal(run({ ...base, elapsedMinutes: "1440" }).ok, true);
});

test("capacity is checked before grammar and range (8 units per scalar field)", () => {
  // weightKg "100000000" is 9 units > 8, even though it is also out of range.
  assert.deepEqual(errorOf({ ...base, weightKg: "100000000" }), {
    code: "INPUT_LIMIT",
    field: "weightKg",
    row: null,
  });
  // elapsedMinutes "000000000" is 9 units.
  assert.deepEqual(errorOf({ ...base, elapsedMinutes: "000000000" }), {
    code: "INPUT_LIMIT",
    field: "elapsedMinutes",
    row: null,
  });
  // Row volume "100000000" is 9 units.
  assert.deepEqual(errorOf({ ...base, drinks: [{ volumeMl: "100000000", abvPercent: "5" }] }), {
    code: "INPUT_LIMIT",
    field: "volumeMl",
    row: 1,
  });
});

test("decimal grammar: two decimals, bare dots, commas, spaces, full-width digits, signs, exponents", () => {
  for (const weightKg of ["70.55", ".5", "70.", "1,000", " 70", "７０", "+70", "7e1"]) {
    assert.deepEqual(
      errorOf({ ...base, weightKg }),
      { code: "DECIMAL_FORMAT", field: "weightKg", row: null },
      `weightKg ${JSON.stringify(weightKg)}`,
    );
  }
  for (const abvPercent of ["5.55", ".5", "5.", "+5", "５"]) {
    assert.deepEqual(
      errorOf({ ...base, drinks: [{ volumeMl: "350", abvPercent }] }),
      { code: "DECIMAL_FORMAT", field: "abvPercent", row: 1 },
      `abvPercent ${JSON.stringify(abvPercent)}`,
    );
  }
});

test("integer grammar: volume 350.0 and elapsed 30.0 are INTEGER_FORMAT; empty is EMPTY", () => {
  assert.deepEqual(errorOf({ ...base, drinks: [{ volumeMl: "350.0", abvPercent: "5" }] }), {
    code: "INTEGER_FORMAT",
    field: "volumeMl",
    row: 1,
  });
  assert.deepEqual(errorOf({ ...base, elapsedMinutes: "30.0" }), {
    code: "INTEGER_FORMAT",
    field: "elapsedMinutes",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, weightKg: "" }), { code: "EMPTY", field: "weightKg", row: null });
  assert.deepEqual(errorOf({ ...base, sex: "" }), { code: "EMPTY", field: "sex", row: null });
  assert.deepEqual(errorOf({ ...base, elapsedMinutes: "" }), {
    code: "EMPTY",
    field: "elapsedMinutes",
    row: null,
  });
});

test("a lone surrogate is UNICODE, after capacity and before grammar", () => {
  assert.deepEqual(errorOf({ ...base, weightKg: "70\uD800" }), {
    code: "UNICODE",
    field: "weightKg",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, elapsedMinutes: "\uDC00" }), {
    code: "UNICODE",
    field: "elapsedMinutes",
    row: null,
  });
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ ...base, sex: "other", weightKg: "x" }), {
    code: "ENUM",
    field: "sex",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, weightKg: "x", elapsedMinutes: "9999" }), {
    code: "DECIMAL_FORMAT",
    field: "weightKg",
    row: null,
  });
  assert.deepEqual(
    errorOf({
      ...base,
      drinks: [
        { volumeMl: "350", abvPercent: "5" },
        { volumeMl: "0", abvPercent: "x" },
      ],
    }),
    { code: "RANGE", field: "volumeMl", row: 2 },
  );
  assert.deepEqual(
    errorOf({
      ...base,
      drinks: [{ volumeMl: "350", abvPercent: "x" }],
      elapsedMinutes: "9999",
    }),
    { code: "DECIMAL_FORMAT", field: "abvPercent", row: 1 },
  );
});

test("schema: extra key, missing key, wrong type, array, null, accessor, and bad row shape are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.drinks;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, weightKg: 70 }), schema);
  assert.deepEqual(errorOf({ ...base, drinks: "350" }), schema);
  assert.deepEqual(errorOf(["male"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("male"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "weightKg", {
    enumerable: true,
    get() {
      return "70";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  // Row shape failures are SCHEMA, not per-row errors.
  assert.deepEqual(errorOf({ ...base, drinks: [{ volumeMl: "350" }] }), schema);
  assert.deepEqual(
    errorOf({ ...base, drinks: [{ volumeMl: "350", abvPercent: "5", extra: "1" }] }),
    schema,
  );
  assert.deepEqual(errorOf({ ...base, drinks: [{ volumeMl: 350, abvPercent: "5" }] }), schema);
  assert.deepEqual(errorOf({ ...base, drinks: [null] }), schema);
  assert.deepEqual(errorOf({ ...base, drinks: ["350"] }), schema);
});

test("band thresholds: exactly 0.300 is administrative, exactly 0.500 is criminal", () => {
  // Exact 0.3: male, 26.3 kg, 680 ml at 1.0%. A = 680 x 1.0% x 0.789
  // = 5.3652 g; r x W = 0.68 x 26.3 = 17.884; P = 5.3652 / 17.884
  // = 0.3 exactly (17.884 x 0.3 = 5.3652). The "reaches" rule (>=)
  // puts it in the administrative band, with 0 minutes to below-admin.
  assert.deepEqual(
    run({ sex: "male", weightKg: "26.3", drinks: [{ volumeMl: "680", abvPercent: "1" }], elapsedMinutes: "0" }),
    {
      ok: true,
      result: {
        totalAlcoholGrams: 5.4,
        peakBacGL: 0.3,
        bacGL: 0.3,
        bacPercent: 0.03,
        breathMgL: 0.15,
        band: "administrative",
        minutesToZero: 120,
        minutesToBelowAdmin: 0,
      },
    },
  );
  // Exact 0.5: female, 78.9 kg, 550 ml at 5.0%. A = 550 x 5.0% x
  // 0.789 = 21.6975 g; r x W = 0.55 x 78.9 = 43.395; P = 21.6975 /
  // 43.395 = 0.5 exactly (43.395 x 0.5 = 21.6975).
  assert.deepEqual(
    run({ sex: "female", weightKg: "78.9", drinks: [{ volumeMl: "550", abvPercent: "5" }], elapsedMinutes: "0" }),
    {
      ok: true,
      result: {
        totalAlcoholGrams: 21.7,
        peakBacGL: 0.5,
        bacGL: 0.5,
        bacPercent: 0.05,
        breathMgL: 0.25,
        band: "criminal",
        minutesToZero: 200,
        minutesToBelowAdmin: 80,
      },
    },
  );
});

test("half-up: an exact-half gram total rounds up, just below rounds down", () => {
  // Exact tie at 1 dp: 500 ml at 10.0% gives A = 500 x 10 x 0.789 /
  // 100 = 39.45 g exactly, so the 1-dp display rounds half-up to 39.5.
  // 499 ml gives A = 39.3711 g, which rounds down to 39.4.
  const tie = run({ sex: "male", weightKg: "70", drinks: [{ volumeMl: "500", abvPercent: "10" }], elapsedMinutes: "0" });
  assert.deepEqual(tie, {
    ok: true,
    result: {
      totalAlcoholGrams: 39.5,
      peakBacGL: 0.829,
      bacGL: 0.829,
      bacPercent: 0.083,
      breathMgL: 0.414,
      band: "criminal",
      minutesToZero: 332,
      minutesToBelowAdmin: 212,
    },
  });
  const below = run({ sex: "male", weightKg: "70", drinks: [{ volumeMl: "499", abvPercent: "10" }], elapsedMinutes: "0" });
  assert.equal(below.ok, true);
  assert.equal(below.result.totalAlcoholGrams, 39.4);
  // The base fixture is just below its own tie: B = 0.29007... rounds
  // to 0.290, and A = 13.8075 g rounds to 13.8.
  const outcome = run(base);
  assert.equal(outcome.result.bacGL, 0.29);
  assert.equal(outcome.result.totalAlcoholGrams, 13.8);
});

test("property over every successful fixture: bacGL <= peakBacGL; more elapsed time never raises bacGL; band matches the fixture; minutes are whole and ordered", () => {
  for (const entry of coreCases) {
    if (!entry.expected.ok) continue;
    const outcome = run(entry.input);
    assert.equal(outcome.ok, true, entry.id);
    const { bacGL, peakBacGL, band, minutesToZero, minutesToBelowAdmin } = outcome.result;
    assert.ok(bacGL <= peakBacGL, `${entry.id}: bacGL <= peakBacGL`);
    const later = run({ ...entry.input, elapsedMinutes: String(Math.min(1440, Number(entry.input.elapsedMinutes) + 60)) });
    assert.equal(later.ok, true, entry.id);
    assert.ok(later.result.bacGL <= bacGL, `${entry.id}: bacGL non-increasing with time`);
    assert.equal(band, entry.expected.result.band, entry.id);
    assert.ok(Number.isInteger(minutesToZero) && Number.isInteger(minutesToBelowAdmin), entry.id);
    assert.ok(minutesToBelowAdmin <= minutesToZero, `${entry.id}: below-admin <= zero`);
    if (band === "below-threshold") assert.equal(minutesToBelowAdmin, 0, entry.id);
    if (bacGL === 0 && entry.id === "beer-male-eliminated") assert.equal(minutesToZero, 0, entry.id);
  }
});

test("display formatting: fixed decimals, no thousands separators", () => {
  assert.equal(formatNumber(0, 3), "0.000");
  assert.equal(formatNumber(0.29, 3), "0.290");
  assert.equal(formatNumber(13.8, 1), "13.8");
  assert.equal(formatNumber(168.545, 3), "168.545");
  assert.equal(formatNumber(47340, 1), "47340.0");
});
